const relLocalVisita = `-- name: RelLocalVisita :many

SELECT b.nome AS bairro, q.nome AS quarteirao, l.endereco, l.numero, l.lado,
       count(v.id)::int AS visitas, max(v.data)::date AS ultima,
       count(v.id) FILTER (WHERE v.achou_deposito)::int AS com_deposito
FROM locais l
JOIN bairros b ON b.id = l.bairro_id
JOIN quarteiroes q ON q.id = l.quarteirao_id
LEFT JOIN visitas v ON v.local_id = l.id AND v.deleted_at IS NULL AND v.ativo
     AND ($1::bigint IS NULL OR v.ciclo_id = $1::bigint)
     AND ($2::bigint IS NULL OR v.atividade_id = $2::bigint)
     AND ($3::text = '' OR v.pendencia = $3::text)
     AND ($4::bigint IS NULL OR v.agente_id = $4::bigint)
WHERE l.deleted_at IS NULL AND l.ativo
  AND ($5::bigint IS NULL OR l.bairro_id = $5::bigint)
  AND ($6::bigint IS NULL OR usuario_ve_local($6::bigint, l.id, l.bairro_id, l.quarteirao_id))
GROUP BY b.nome, q.nome, l.id
HAVING ($7::text = '' OR ($7::text = 'sim') = (count(v.id) > 0))
ORDER BY b.nome, q.nome, l.endereco, l.numero
LIMIT 20001
`

type RelLocalVisitaParams struct {
	CicloID        pgtype.Int8 `json:"ciclo_id"`
	AtividadeID    pgtype.Int8 `json:"atividade_id"`
	Pendencia      string      `json:"pendencia"`
	SomenteAgente  pgtype.Int8 `json:"somente_agente"`
	BairroID       pgtype.Int8 `json:"bairro_id"`
	SomenteUsuario pgtype.Int8 `json:"somente_usuario"`
	Situacao       string      `json:"situacao"`
}

type RelLocalVisitaRow struct {
	Bairro      string      `json:"bairro"`
	Quarteirao  string      `json:"quarteirao"`
	Endereco    string      `json:"endereco"`
	Numero      string      `json:"numero"`
	Lado        string      `json:"lado"`
	Visitas     int32       `json:"visitas"`
	Ultima      pgtype.Date `json:"ultima"`
	ComDeposito int32       `json:"com_deposito"`
}

// Consultas dos relatórios do sistema (8.2). Cada uma devolve linhas já agregadas para o motor de relatórios.
